{
  "lines": [
    {
      "text": "Lwif aͤß Köniͤgßberg, den 29. Juliuͤß 1786"
    },
    {
      "text": "Liebſte Schweſter!"
    },
    {
      "text": "Geſtern ſind wir glüͤcklich in Köniͤgßberg angekommen, nachdem ſich der Weg von Elbing"
    },
    {
      "text": "uͤber die Uſſring zwoͤlf volle Tage geſtoͤßet hat. Der Sand iſt tief und die Pferde waren"
    },
    {
      "text": "müde. Wir woͤhnen bey dem Kaufmann Falbergß am Pregel, deſſen Frau Sie grüßen"
    },
    {
      "text": "läßt."
    },
    {
      "text": "Heute Vormittag ſahen wir den Profeſſor Kant beſucht. Er iſt klein und freundlich und"
    },
    {
      "text": "ſpricht von allem, nur nicht von ſeinen Bücher. Morgen ſahren wir nach Memel, und von"
    },
    {
      "text": "da, ſo Gott will, über Tilsit zurück."
    },
    {
      "text": "Schreibt mir nach Danzig, poſta reſtante. Ich bin und bleibe Euer treuer Bruder"
    },
    {
      "text": "Friedrich."
    }
  ],
  "script": "kurrent",
  "notes": "Handwritten in Kurrent script. Some letters are ligatured or faint. Date and salutation are centered. No visible damage or bleed-through."
}

